import{t,subscribeLanguage}from './i18n.js';
import{uiLeaf,uiAttribute,uiTextAttributes,setUiMessage,uiMessage,uiError,setUiAttribute}from './ui.js';
import{paintStaffUi,staffErrorMessage}from './staff-ui.js';
import{mountMessageEmoji}from './message-emojis.js';
const docWindow=root=>root.ownerDocument.defaultView||window;
import{escapeStaff as esc,staffIcon as icon,roleLabel,roleMarkup}from './staff-markup.js';
const initials=name=>[...String(name||'С').trim()].slice(0,2).join('').toUpperCase();
export function staffMessengerMarkup(){return "<div class=\"staff-chat staff-messenger\" data-messenger-view=\"list\"><aside class=\"staff-chat-side\"><header class=\"staff-inbox-heading\"><h2>"+uiLeaf("staffUi.chatConversations")+"</h2><span class=\"staff-inbox-count\" data-inbox-count></span><button type=\"button\" class=\"staff-icon-button\" data-new-message "+uiAttribute("staffUi.chatNewMessage",{},"aria-label")+" aria-pressed=\"false\">"+icon('plus')+'</button></header><label class="staff-chat-search">'+icon('messages')+"<input type=\"search\" maxlength=\"80\" "+uiAttribute("staffUi.chatSearch",{},"aria-label")+" "+uiAttribute("staffUi.chatSearch",{},"placeholder")+"></label><nav class=\"staff-inbox-filters\" "+uiAttribute("staffUi.chatConversations",{},"aria-label")+"><button type=\"button\" data-inbox-filter=\"all\" aria-pressed=\"true\">"+uiLeaf("staffUi.chatAll")+"</button><button type=\"button\" data-inbox-filter=\"direct\" aria-pressed=\"false\">"+uiLeaf("staffUi.chatDirect")+"</button><button type=\"button\" data-inbox-filter=\"team\" aria-pressed=\"false\">"+uiLeaf("staffUi.chatTeam")+"</button></nav><h3 class=\"staff-inbox-label\">"+uiLeaf("staffUi.chatConversations")+"</h3><div data-rooms></div><h3 class=\"staff-inbox-label\">"+uiLeaf("staffUi.chatContact")+"</h3><div data-contacts></div></aside><dialog class=\"staff-conversation-window\" "+uiAttribute("staffUi.chatConversation",{},"aria-label")+"><section class=\"staff-conversation\"><header class=\"staff-chat-heading\"><button type=\"button\" class=\"staff-icon-button\" data-messenger-back "+uiAttribute("staffUi.chatBack",{},"aria-label")+">"+icon('back')+"</button><span class=\"staff-conversation-avatar\" aria-hidden=\"true\" data-conversation-avatar>С</span><div><strong data-chat-title>"+uiLeaf("staffUi.chatTeamTitle")+"</strong><small data-chat-subtitle>"+uiLeaf("staffUi.chatTeamSubtitle")+"</small></div></header><div data-staff-push-control></div><p class=\"staff-conversation-status\" role=\"status\" hidden></p><div class=\"staff-chat-messages\" role=\"log\" "+uiAttribute("staffUi.chatConversation",{},"aria-label")+" aria-live=\"polite\" aria-relevant=\"additions text\"></div><form class=\"staff-composer\"><div class=\"staff-pending-files\"></div><div class=\"staff-emoji\" hidden>"+['🙂','😊','🤍','👍','🤲','🙏','✨','🌙','✅','👏','💬','📌'].map(x=>'<button type="button" data-emoji="'+x+'" aria-label="'+x+'">'+x+'</button>').join('')+"</div><div class=\"staff-composer-row\"><button class=\"staff-icon-button\" type=\"button\" data-smile "+uiAttribute("staffUi.chatEmoji",{},"aria-label")+" aria-expanded=\"false\">"+icon('smile')+"</button><button class=\"staff-icon-button\" type=\"button\" data-attach "+uiAttribute("staffUi.chatAttach",{},"aria-label")+">"+icon('file')+"</button><textarea maxlength=\"5000\" "+uiAttribute("staffUi.chatMessage",{},"aria-label")+" "+uiAttribute("staffUi.chatMessagePlaceholder",{},"placeholder")+"></textarea><button class=\"staff-icon-button staff-send\" type=\"submit\" "+uiAttribute("staffUi.chatSend",{},"aria-label")+">"+icon('send')+'</button><input type="file" hidden multiple data-chat-file accept=".pdf,.txt,.jpg,.jpeg,.png,.zip,.docx,.xlsx,.pptx"></div></form></section></dialog></div>';}
export function mountStaffMessenger(root,{rooms=[],contacts=[],onRoom,onContact,onRendered=()=>{},initialRoom=null,pinScope=null}={}){
 const win=docWindow(root),doc=root.ownerDocument,dialog=root.querySelector('dialog'),input=root.querySelector('textarea'),list=root.querySelector('[data-rooms]'),people=root.querySelector('[data-contacts]'),search=root.querySelector('input[type=search]'),newButton=root.querySelector('[data-new-message]');
 const composer=input.closest('form'),emoji=mountMessageEmoji(input,{button:root.querySelector('[data-smile]'),panel:root.querySelector('.staff-emoji')});
 const history=win.history,historyKey='salahStaffChat',token=String(Date.now())+'-'+Math.random().toString(36).slice(2);let selected=null,filter='all',query='',newMessage=false,disposed=false,previousState=null,narrow=true,wasModal=false,backPending=false;
 const pinKey=typeof pinScope==='string'&&/^[\w-]{1,80}$/.test(pinScope)?'salah-staff-pins-v1:'+pinScope:null;let pinned=new Set(rooms.filter(r=>r.kind==='team').map(r=>r.id));if(pinKey)try{const saved=win.localStorage.getItem(pinKey);if(saved!==null){const ids=JSON.parse(saved);if(Array.isArray(ids)&&ids.length<=100)pinned=new Set(ids.filter(id=>typeof id==='string'&&/^[\w-]{1,80}$/.test(id)));}}catch{}
 const ownsEntry=()=>history?.state?.[historyKey]===token;
 const stripMarker=()=>{if(history?.state?.[historyKey]){const state={...history.state};delete state[historyKey];history.replaceState(state,'',win.location.href);}};
 stripMarker();
 let viewportWidth=0,restingHeight=0;
 function viewport(){if(disposed)return;const box=root.getBoundingClientRect();narrow=(win.innerWidth||0)<720||box.width<600;const visual=win.visualViewport,height=visual?.height||win.innerHeight||800,top=visual?.offsetTop||0,width=visual?.width||win.innerWidth||box.width;
  if(Math.abs(width-viewportWidth)>2){viewportWidth=width;restingHeight=win.innerHeight||height;}
  restingHeight=Math.max(restingHeight,height);
  const keyboard=narrow&&dialog.contains(doc.activeElement)&&(visual?.scale||1)<=1.05&&Math.max(restingHeight,win.innerHeight||height)-height>100;
  dialog.classList.toggle('is-keyboard-open',keyboard);dialog.classList.toggle('is-emoji-open',emoji.isOpen());
  dialog.style.setProperty('--staff-chat-input-max-height',Math.min(124,Math.max(46,Math.floor(height*.24)))+'px');root.style.setProperty('--staff-conversation-height',Math.round(Math.min(740,height-100))+'px');dialog.style.setProperty('--staff-chat-viewport-height',Math.round(height)+'px');dialog.style.setProperty('--staff-chat-viewport-top',Math.round(top)+'px');const modal=narrow&&root.dataset.messengerView==='chat';doc.body.classList.toggle('staff-messenger-open',modal);dialog.classList.toggle('is-mobile',narrow);
  if(modal){if(dialog.open&&!wasModal)dialog.close();if(!dialog.open){dialog.showModal();root.querySelector('[data-messenger-back]').focus({preventScroll:true});}wasModal=true;}
  else{if(dialog.open&&wasModal)dialog.close();wasModal=false;if(!narrow&&!dialog.open)dialog.show();if(narrow&&dialog.open)dialog.close();}
 }
 const typing=()=>{if(disposed)return;doc.body.classList.toggle('staff-messenger-typing',narrow&&doc.activeElement===input);viewport();};
 const emojiChanged=()=>viewport();composer.addEventListener('salah:emoji-mode',emojiChanged);
 const onBlur=()=>queueMicrotask(typing);input.addEventListener('focus',typing);input.addEventListener('blur',onBlur);
 const resizeInput=()=>{input.style.height='auto';input.style.height=Math.max(46,Math.min(124,input.scrollHeight||46))+'px';};input.addEventListener('input',resizeInput);
 const roomTitle=room=>room.titleUiKey==='staffUi.cabinetEmployee'?t(room.titleUiKey):room.title||t('staffUi.chatConversation');
 function paintLabels(){if(disposed)return;paintStaffUi(root);for(const button of list.querySelectorAll('[data-room]')){const room=rooms.find(item=>item.id===button.dataset.room);if(!room)continue;const title=roomTitle(room);if(!room.title||room.titleUiKey==='staffUi.cabinetEmployee')button.querySelector('.staff-room-copy strong').textContent=title;const pin=button.parentElement.querySelector('[data-room-pin]');if(pin)setUiAttribute(pin,'aria-label',pinned.has(room.id)?'staffUi.chatUnpin':'staffUi.chatPin',{title});}if(selected){const title=root.querySelector('[data-chat-title]');if(!selected.title||selected.titleUiKey==='staffUi.cabinetEmployee')title.textContent=roomTitle(selected);}}
 const offLanguage=subscribeLanguage(paintLabels);
 function renderRooms(rows=rooms,current=selected){if(disposed)return;rooms=rows;selected=current;const count=rooms.reduce((sum,r)=>sum+(Number.isSafeInteger(r.unread)&&r.unread>0?r.unread:0),0);root.querySelector('[data-inbox-count]').textContent=count?(count>99?'99+':String(count)):'';
  const visible=rooms.filter(r=>(filter==='all'||(filter==='team')===(r.kind==='team'))&&roomTitle(r).toLowerCase().includes(query)).sort((a,b)=>Number(pinned.has(b.id))-Number(pinned.has(a.id))||(pinned.has(a.id)&&pinned.has(b.id)?Number(b.kind==='team')-Number(a.kind==='team'):0));
  list.hidden=newMessage;list.previousElementSibling.hidden=true;
  list.innerHTML=visible.length?visible.map(r=>'<div class="staff-room-item"><button type="button" class="staff-chat-room" data-room="'+esc(r.id)+'" aria-current="'+(r.id===selected?.id)+'"><span class="staff-room-avatar'+(r.peerId?' staff-avatar':'')+'"'+(r.peerId?' data-member-avatar="'+esc(r.peerId)+'"':'')+' aria-hidden="true">'+(r.kind==='team'?icon('team'):esc(initials(roomTitle(r))))+'</span><span class="staff-room-copy"><strong>'+esc(roomTitle(r))+'</strong><small>'+(r.previewPending?uiLeaf('staffUi.cabinetLoading'):r.last_message?esc(r.last_message):uiLeaf('staffUi.chatStartConversation'))+'</small></span>'+(r.unread?'<span class="staff-room-unread" '+uiAttribute('staffUi.chatUnread',{count:r.unread})+'>'+esc(r.unread>99?'99+':r.unread)+'</span>':'')+'</button><button type="button" class="staff-room-pin" data-room-pin="'+esc(r.id)+'" '+uiAttribute(pinned.has(r.id)?'staffUi.chatUnpin':'staffUi.chatPin',{title:roomTitle(r)})+' aria-pressed="'+pinned.has(r.id)+'">'+icon('pin')+'</button></div>').join(''):'<p class="staff-empty">'+uiLeaf(query?'staffUi.chatNotFound':'staffUi.chatEmpty')+'</p>';
  const showPeople=filter!=='team'&&(newMessage||!!query);people.hidden=!showPeople;people.previousElementSibling.hidden=!showPeople;people.innerHTML=showPeople?contacts.filter(p=>String(p.nickname||'').toLowerCase().includes(query)).map(p=>'<button type="button" class="staff-chat-room staff-chat-contact" data-contact="'+esc(p.id)+'"><span class="staff-avatar staff-room-avatar" data-member-avatar="'+esc(p.id)+'" aria-hidden="true">'+esc(initials(p.nickname))+'</span><span class="staff-room-copy"><strong>'+esc(p.nickname)+'</strong><small>'+roleMarkup(p.role)+'</small></span></button>').join(''):'';
  if(showPeople&&!people.childElementCount)people.innerHTML="<p class=\"staff-empty\">"+uiLeaf("staffUi.chatNoContacts")+"</p>";newButton.setAttribute('aria-pressed',String(newMessage));setUiAttribute(newButton,'aria-label',newMessage?'staffUi.chatBack':'staffUi.chatNewMessage');onRendered();
 }
 function showConversation(room){if(disposed||!room||backPending)return;emoji.close();selected=room;const opening=root.dataset.messengerView!=='chat';root.dataset.messengerView='chat';root.querySelector('[data-chat-title]').textContent=roomTitle(room);setUiMessage(root.querySelector('[data-chat-subtitle]'),uiMessage(room.kind==='team'?'staffUi.chatTeamSubtitle':'staffUi.chatDirectSubtitle'));const avatar=root.querySelector('[data-conversation-avatar]');if(room.peerId){avatar.dataset.memberAvatar=room.peerId;avatar.classList.add('staff-avatar');}else{delete avatar.dataset.memberAvatar;avatar.classList.remove('staff-avatar');}avatar.innerHTML=room.kind==='team'?icon('team'):esc(initials(roomTitle(room)));renderRooms(rooms,selected);viewport();if(opening&&narrow&&history&&!ownsEntry()){previousState=history.state;try{history.pushState({...previousState,[historyKey]:token},'',win.location.href);}catch{}}
 }
 function showList({back=false}={}){if(disposed)return;emoji.close();root.dataset.messengerView='list';input.blur();doc.body.classList.remove('staff-messenger-typing');viewport();const heading=root.querySelector('.staff-inbox-heading h2');heading.tabIndex=-1;heading.focus({preventScroll:true});if(back&&!backPending&&ownsEntry()){backPending=true;history.back();}}
 const pop=()=>{if(disposed)return;backPending=false;if(root.dataset.messengerView==='chat'&&!ownsEntry())showList();else if(ownsEntry()&&root.dataset.messengerView!=='chat')stripMarker();};win.addEventListener('popstate',pop);
 const cancel=e=>{e.preventDefault();showList({back:true});};dialog.addEventListener('cancel',cancel);root.querySelector('[data-messenger-back]').onclick=()=>showList({back:true});
 list.onclick=e=>{const pin=e.target.closest('[data-room-pin]');if(pin){const id=pin.dataset.roomPin;if(pinned.has(id))pinned.delete(id);else pinned.add(id);if(pinKey)try{win.localStorage.setItem(pinKey,JSON.stringify([...pinned].slice(0,100)));}catch{}renderRooms();list.querySelector('[data-room-pin="'+id+'"]')?.focus({preventScroll:true});return;}const b=e.target.closest('[data-room]');if(b)onRoom(rooms.find(r=>r.id===b.dataset.room));};people.onclick=e=>{const b=e.target.closest('[data-contact]');if(b)onContact(b.dataset.contact);};
 search.oninput=()=>{query=search.value.trim().toLowerCase();renderRooms();};newButton.onclick=()=>{newMessage=!newMessage;filter='all';for(const b of root.querySelectorAll('[data-inbox-filter]'))b.setAttribute('aria-pressed',String(b.dataset.inboxFilter===filter));renderRooms();};for(const button of root.querySelectorAll('[data-inbox-filter]'))button.onclick=()=>{filter=button.dataset.inboxFilter;newMessage=false;for(const b of root.querySelectorAll('[data-inbox-filter]'))b.setAttribute('aria-pressed',String(b===button));renderRooms();};
 win.addEventListener('resize',viewport);win.visualViewport?.addEventListener('resize',viewport);win.visualViewport?.addEventListener('scroll',viewport);renderRooms();viewport();if(initialRoom){const row=rooms.find(r=>r.id===initialRoom);if(row)showConversation(row);}
 return{renderRooms,showConversation,isConversationVisible:()=>root.dataset.messengerView==='chat'||!narrow,dispose(){if(disposed)return;disposed=true;offLanguage();emoji.dispose();composer.removeEventListener('salah:emoji-mode',emojiChanged);if(ownsEntry())history.replaceState(previousState,'',win.location.href);if(dialog.open)dialog.close();doc.body.classList.remove('staff-messenger-typing','staff-messenger-open');input.removeEventListener('focus',typing);input.removeEventListener('blur',onBlur);input.removeEventListener('input',resizeInput);win.removeEventListener('resize',viewport);win.removeEventListener('popstate',pop);win.visualViewport?.removeEventListener('resize',viewport);win.visualViewport?.removeEventListener('scroll',viewport);dialog.removeEventListener('cancel',cancel);}};
}
